46	
47	    const byMonthMap = new Map<string, number>();
48	    notas.forEach((nota) => {
49	      const date = new Date(nota.data_nota || nota.created_at);
50	      const key = String(date.getFullYear()) + '-' + String(date.getMonth() + 1).padStart(2, '0');
51	      const prev = byMonthMap.get(key) || 0;
52	      byMonthMap.set(key, prev + (parseFloat(nota.valor_total || '0') || 0));
53	    });
54	
55	    const byMonth = Array.from(byMonthMap.entries())
56	      .map(([name, value]) => ({ name, value }))
