64	      if (prev) {
65	        prev.value += parseFloat(nota.valor_total || '0') || 0;
66	      } else {
67	        bySupplierMap.set(key, { display: raw, value: parseFloat(nota.valor_total || '0') || 0 });
68	      }
69	    });
70	
71	    const topSuppliers = Array.from(bySupplierMap.values())
72	      .map(({ display, value }) => ({ name: display, value }))
73	      .sort((a, b) => b.value - a.value)
